import {listProjects} from './project-model.js';
import {APP_VERSION} from './version.js';
export const BRAND='GameDesignerWorkerSpace';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>/^\d{4}-\d{2}-\d{2}/.test(value||'')?(value.includes('T')?new Date(value).toLocaleDateString('sv-SE'):value.slice(0,10)).replaceAll('-','.'):'';
export function brandMarkup(icon,library=false){return `<button class="brand ${library?'library-brand':''}" data-page="library" aria-label="${BRAND} 项目库" title="${BRAND}"><span class="brandmark">${icon('game')}</span><span class="brand-wordmark"><span class="brand-name">GameDesigner<wbr>WorkerSpace</span><small>DESIGN. BUILD. PLAY.</small></span></button>`;}
export function libraryMarkup({state,query='',deleted=false,status,icon,projectInfo={},issues=[]}){
 const active=listProjects(state),recycled=listProjects(state,{deleted:true}),projects=listProjects(state,{deleted,query});
 const tasks=active.reduce((n,p)=>n+p.tasks.filter(t=>t.status!=='done').length,0),docs=active.reduce((n,p)=>n+p.docs.length,0);
 return `<div class="project-library"><header class="library-header">${brandMarkup(icon,true)}<div class="library-header-meta"><span class="library-local">${icon('folder')}本地项目工作空间</span><span class="library-user">GD</span></div></header><main class="library-main"><div class="library-heading"><div><p class="eyebrow">YOUR GAME PROJECTS</p><h1>${deleted?'项目回收站':'项目库'}</h1><p class="subtitle">${deleted?'被删除的项目保留在这里，随时可以恢复。':'从一个想法开始，创造下一个游戏世界。'}</p></div><div class="heading-actions">${deleted&&recycled.length?`<button class="btn danger" data-action="purge-trash">${icon('close')}清空回收站</button>`:''}<button class="btn" data-action="attach-folder">${icon('folder')}关联文件夹</button><button class="btn" data-action="import-link">${icon('link')}链接导入</button><button class="btn" data-action="import">${icon('upload')}JSON 备份</button><button class="btn primary" data-action="new-project">${icon('plus')}新建项目</button></div></div><section class="library-summary" aria-label="项目库统计"><div><span class="library-summary-icon">${icon('folder')}</span><span><strong>${active.length}</strong> 个游戏项目</span></div><i></i><div><span><strong>${tasks}</strong> 项待办任务</span></div><i></i><div><span><strong>${docs}</strong> 份策划文档</span></div><p>每个世界，都从这里出发。</p></section><div class="library-toolbar"><div class="library-tabs"><button class="library-tab ${!deleted?'active':''}" data-library-tab="active">全部项目<span>${active.length}</span></button><button class="library-tab ${deleted?'active':''}" data-library-tab="deleted">项目回收站<span>${recycled.length}</span></button></div><label class="library-search">${icon('search')}<input id="library-search" type="search" placeholder="搜索项目名称、类型、引擎…" aria-label="搜索项目库" value="${esc(query)}"></label></div>${issues.length?`<div class="library-issues">${issues.map(item=>`<div class="notice"><strong>${esc(item.name||item.id)}</strong><p>${esc(item.error)}</p><p>${esc(item.directory)}</p><button class="btn" data-action="attach-folder">重新关联目录</button><button class="btn" data-project-repo="${item.id}">仓库状态</button><button class="btn" data-project-upload="${item.id}">上传</button><button class="btn" data-project-update="${item.id}">更新</button></div>`).join('')}</div>`:''}<div class="library-projects">${projects.map((p,i)=>projectCard(p,{deleted,icon,i,info:projectInfo[p.id]||{}})).join('')}${!deleted&&!query?`<button class="library-new-card" data-action="new-project"><span>${icon('plus')}</span><strong>下一个世界，等你创造</strong><p>为你的游戏起一个名字，开始创作。</p><b>创建新项目 ${icon('arrow')}</b></button>`:''}${!projects.length&&(query||deleted)?`<div class="library-empty">${icon(deleted?'folder':'search')}<h2>${deleted?'回收站是空的':'没有找到匹配项目'}</h2><p>${deleted?'从项目库删除的项目可以在这里恢复。':'换个关键词，寻找你的游戏项目。'}</p></div>`:''}</div><aside class="library-storage"><span>${icon('folder')}</span><div><strong>你的内容，和项目放在一起。</strong><p>每个项目保存为独立文件夹，Git / SVN 链接只绑定该项目。工作台升级与项目内容分开管理。</p></div><button class="text-link" data-action="check-app-update">${icon('download')}工作台更新</button><button class="text-link" data-action="tools-info">${icon('box')}内置依赖</button><button class="text-link" data-action="reload-disk">${icon('download')}重新读取项目</button></aside><footer class="library-footer"><span>${BRAND} <b>·</b> 应用 v${APP_VERSION} / 项目格式 v1</span><span class="disk-status">${esc(status)}</span></footer></main></div>`;
}
function projectCard(p,{deleted,icon,i,info}){
 const done=p.tasks.filter(t=>t.status==='done').length,rate=p.tasks.length?Math.round(done/p.tasks.length*100):0;
 const updated=[p.created,...p.docs.map(d=>d.updated),...p.tasks.map(t=>t.updated)].filter(Boolean).sort().at(-1);
 return `<article class="library-project-card ${deleted?'is-deleted':''}" data-project-card="${p.id}"><${deleted?'div':'button'} class="library-project-cover cover-${i%3}" ${deleted?'':`data-open-project="${p.id}" aria-label="进入项目：${esc(p.name)}"`}><span class="library-stage">${deleted?'已移入回收站':esc(p.stage)}</span><span class="cover-caption">${deleted?'YOUR WORLD IS STILL HERE.':'A NEW WORLD IS GROWING.'}</span>${info.type&&info.type!=='local'?`<span class="library-repo-badge">${esc(info.type.toUpperCase())}</span>`:''}${!deleted?`<span class="cover-enter">${icon('arrow')}</span>`:''}</${deleted?'div':'button'}><div class="library-card-body"><div class="library-project-tags"><span>${esc(p.engine)}</span><span>${esc(p.genre)}</span></div><${deleted?'h2':'button'} class="library-project-name" ${deleted?'':`data-open-project="${p.id}"`} title="${esc(p.name)}">${esc(p.name)}</${deleted?'h2':'button'}><p class="library-project-desc">${esc(p.desc||'一个新的游戏世界，正等待你来创造。')}</p><div class="library-project-stats"><span>${icon('tasks')}${p.tasks.length} 个任务</span><span>${icon('doc')}${p.docs.length} 份文档</span><span>${icon('mind')}${p.docs.reduce((n,d)=>n+d.diagrams.length,0)} 张图表</span></div>${!deleted?`<div class="library-card-progress"><div class="progress"><span style="width:${rate}%"></span></div><span>${p.tasks.length?rate+'%':'准备启程'}</span></div>`:`<p class="library-deleted-date">删除于 ${date(p.deletedAt)} · 内容可以完整恢复</p>`}<div class="library-card-footer">${deleted?`<span>原项目文件已保留</span><div class="library-trash-actions"><button class="btn danger" data-purge-project="${p.id}">彻底删除</button><button class="btn primary" data-restore-project="${p.id}">${icon('arrow')}恢复项目</button></div>`:`<span title="最近编辑">${date(updated)||'刚刚创建'}</span><div class="library-card-actions"><button aria-label="重命名项目：${esc(p.name)}" title="重命名项目" data-rename-project="${p.id}">${icon('pen')}</button><button aria-label="删除项目：${esc(p.name)}" title="删除项目" data-delete-project="${p.id}">${icon('close')}</button><button class="btn" data-open-project="${p.id}">进入项目 ${icon('arrow')}</button></div>`}</div>${!deleted?`<div class="library-repository-row"><button data-project-repo="${p.id}">${icon('settings')}${info.type&&info.type!=='local'?esc(info.type.toUpperCase())+' 仓库':'绑定独立仓库'}</button>${info.type&&info.type!=='local'?`<button data-project-update="${p.id}">${icon('download')}更新</button>`:''}<button class="repo-upload" data-project-upload="${p.id}">${icon('upload')}上传</button></div>`:''}</div></article>`;
}
